pragma solidity >=0.8.0;
contract EventOverloadReplay {
    event Ping(uint256 a);
    event Ping(uint256 a, string s);
    uint256 public last;

    function mix() public {
        emit Ping(1);
        emit Ping(10, "a");
        emit Ping(2);
        emit Ping(20, "b");
        last = 4;
    }

    function get() public view returns (uint256) {
        return last;
    }
}
